quickstart.python:
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("dictionary")

@mcp.tool()
def define(term: str) -> str:
    """Look up a term in the AI dictionary."""
    return f"{term}: ..."

if __name__ == "__main__":
    mcp.run()   # stdio server an MCP client can launch

quickstart.javascript:
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

const server = new McpServer({ name: "dictionary", version: "1.0.0" });
server.tool("define", { term: z.string() }, async ({ term }) => ({
  content: [{ type: "text", text: term + ": ..." }],
}));
await server.connect(new StdioServerTransport());
